// Settings. For a first run you only need to connect your Google Sheet and your ReplyNodes API key.
//
// Company search is 1 credit per lookup that finds a company. Lookups that find nothing are free.
// The API allows one search at a time and 60 per minute, so the workflow looks up one domain at a time
// and pauses spacingSeconds between rows.
return [
  {
    json: {
      apiBase: 'https://api.replynodes.com',
      mdBase: 'https://md.replynodes.com',
      spacingSeconds: 1.2,
      // Pause before the single retry after a 504 (the API asks for a 30 second pause).
      retryAfter504Seconds: 30,
      // Sent as the X-Source header so ReplyNodes can count usage of this template.
      // Delete the header in the HTTP Request nodes if you prefer not to send it.
      sourceHeader: 'n8n-company-research/enrich-by-domain',
    },
  },
];

// Keep rows with a domain and an empty status, normalize the domain, and flag rows that
// should not trigger a lookup (invalid domain, or a duplicate of an earlier row in this run).
function normalizeDomain(raw) {
  let s = String(raw ?? '').trim().toLowerCase();
  if (!s) return '';
  s = s.replace(/^[a-z][a-z0-9+.-]*:\/\//, ''); // protocol
  s = s.split(/[/?#]/)[0]; // path, query, hash
  s = s.replace(/^[^@]*@/, ''); // credentials
  s = s.replace(/:\d+$/, ''); // port
  s = s.replace(/\.$/, '').replace(/^www\./, '');
  return /^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+$/.test(s) ? s : '';
}

const seen = new Set();
const out = [];
for (const item of $input.all()) {
  const row = item.json;
  const raw = String(row.domain ?? '').trim();
  const status = String(row.status ?? '').trim();
  if (!raw || status) continue; // already processed (or empty line)
  const domain = normalizeDomain(raw);
  let skip = '';
  if (!domain) skip = 'invalid_domain';
  else if (seen.has(domain)) skip = 'duplicate';
  else seen.add(domain);
  out.push({ json: { row_number: row.row_number, input: raw, domain, skip } });
}
return out;

// Rows that are not looked up still get a status, so a re-run does not retry them blindly.
const blank = {
  status: '', source: '', name: '', description: '', industries: '', hq_country: '', hq_region: '',
  employees_min: '', employees_max: '', funding_total_usd: '', latest_round_type: '',
  latest_round_date: '', data_loaded_at: '', checked_at: new Date().toISOString(), error: '',
};
const item = $input.item.json;
const reason = item.skip === 'duplicate'
  ? 'same domain appears earlier in this run'
  : 'not a valid domain';
return { json: { ...blank, row_number: item.row_number, domain: item.input,
  status: item.skip === 'duplicate' ? 'skipped_duplicate' : 'error', error: item.skip + ': ' + reason } };

// Decide whether the response deserves the single retry (429, 503, 504 or no response at all)
// and how long to wait first.
const res = $input.item.json;
const s = res.statusCode;
const cfg = $('Settings').first().json;
const retry = !s || s === 429 || s === 503 || s === 504;
const retryAfter = parseInt((res.headers || {})['retry-after'], 10);
const floor = s === 504 ? cfg.retryAfter504Seconds : 1;
const base = s === 504 ? cfg.retryAfter504Seconds : 5;
const wait = Math.min(Math.max(Number.isNaN(retryAfter) ? base : retryAfter, floor), 120);
return { json: { ...res, _retry: retry, _waitSeconds: wait } };

// Accept a hit only when its domain equals the domain we asked for. A near match is not a match.
function normalizeDomain(raw) {
  let s = String(raw ?? '').trim().toLowerCase();
  if (!s) return '';
  s = s.replace(/^[a-z][a-z0-9+.-]*:\/\//, ''); // protocol
  s = s.split(/[/?#]/)[0]; // path, query, hash
  s = s.replace(/^[^@]*@/, ''); // credentials
  s = s.replace(/:\d+$/, ''); // port
  s = s.replace(/\.$/, '').replace(/^www\./, '');
  return /^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+$/.test(s) ? s : '';
}
function companyToRow(c, loadedAt) {
  const funding = c.funding || {};
  const round = funding.latest_round || {};
  const hq = c.headquarters || {};
  const emp = c.employees || {};
  return {
    status: 'found',
    source: 'replynodes_db',
    name: c.name ?? '',
    description: c.description ?? '',
    industries: Array.isArray(c.industries) ? c.industries.join('; ') : '',
    hq_country: hq.country_code ?? '',
    hq_region: hq.region ?? '',
    employees_min: emp.min ?? '',
    employees_max: emp.max ?? '',
    funding_total_usd: funding.total_usd ?? '',
    latest_round_type: round.type ?? '',
    latest_round_date: round.date ?? '',
    data_loaded_at: loadedAt ?? '',
    checked_at: new Date().toISOString(),
    error: '',
  };
}
const blank = {
  status: '', source: '', name: '', description: '', industries: '', hq_country: '', hq_region: '',
  employees_min: '', employees_max: '', funding_total_usd: '', latest_round_type: '',
  latest_round_date: '', data_loaded_at: '', checked_at: new Date().toISOString(), error: '',
};
const item = $('Loop over domains').item.json;
const res = $input.item.json;
const s = res.statusCode;
const body = res.body && typeof res.body === 'object' ? res.body : {};
// Keep the domain exactly as the user typed it, so the sheet cell is not rewritten.
const base = { ...blank, row_number: item.row_number, domain: item.input };

if (s === 200 && body.data && Array.isArray(body.data.results)) {
  const hit = body.data.results.find((r) => normalizeDomain(r.domain) === item.domain);
  if (hit) return { json: { ...base, ...companyToRow(hit, body.data.loaded_at), _fallback: false } };
  return { json: { ...base, status: 'not_found', data_loaded_at: body.data.loaded_at ?? '',
    error: 'not in the company database', _fallback: true } };
}

let detail = '';
if (!s) detail = (res.error && (res.error.message || res.error.description)) || 'no response';
else {
  const e = body.error || {};
  detail = 'HTTP ' + s + (e.message ? ': ' + e.message : (e.code ? ': ' + e.code : ''));
  if (s === 401) detail += ' (check the ReplyNodes API credential)';
  if (s === 402) detail += ' (out of credits)';
}
return { json: { ...base, status: 'error', error: detail, _fallback: false } };

// Fallback for companies missing from the database: take name and description from the live site.
// No headcount or funding is guessed.
const prev = $('Evaluate search').item.json;
const res = $input.item.json;
const row = { ...prev };
delete row._fallback;
const md = res.statusCode === 200 && res.body && res.body.data ? res.body.data.metadata || {} : null;
if (md && (md.site_name || md.title || md.description)) {
  row.status = 'found_live_only';
  row.source = 'live_site';
  row.name = md.site_name || md.title || '';
  row.description = md.description || '';
  row.error = '';
  row.checked_at = new Date().toISOString();
} else {
  row.error = 'not in the company database; live site fetch failed' + (res.statusCode ? ' (HTTP ' + res.statusCode + ')' : '');
}
return { json: row };

// Rows that go straight to the sheet carry no internal flags.
const row = { ...$input.item.json };
delete row._fallback;
return { json: row };

// Counts per status for this run.
const written = $('Write row').all().length;
return [{ json: { rows_written: written, note: 'See the sheet for per-row status. Re-run to retry rows with an empty status.' } }];
